<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ServiceProvider} from '@/services/service-provider';const props=defineProps<{id:string}>();const router=useRouter();const form=reactive({firstName:'',lastName:'',email:'',username:'',password:'',age:0,gender:'',phone:''});const loading=ref(true);const message=ref('');onMounted(async()=>{try{Object.assign(form,await ServiceProvider.users.getById(Number(props.id)))}catch(e){message.value=(e as Error).message}finally{loading.value=false}});async function save(){try{await ServiceProvider.users.update(Number(props.id),form);router.push(`/users/${props.id}`)}catch(e){message.value=(e as Error).message}}</script>
<template><section class="narrow"><RouterLink class="back" :to="`/users/${props.id}`">← До профілю</RouterLink><div class="card"><p class="eyebrow">EDIT USER</p><h1>Редагування користувача</h1><form v-if="!loading" class="form-grid" @submit.prevent="save"><label v-for="key in ['firstName','lastName','email','username','password','age','gender','phone']" :key="key">{{key}}<input v-model="form[key as keyof typeof form]" :type="key==='password'?'password':key==='age'?'number':'text'" :required="key!=='password'"/></label><p v-if="message" class="error">{{message}}</p><button class="button">Зберегти</button></form><p v-else>Завантаження...</p></div></section></template>
